    <Badge
      key={status}
      data-cy="test-status-badge"
      variant={statusToBadgeColor[testStatus] || Variant.LightGray}
    >
      {statusToCopy[testStatus] || status}
    </Badge>
  );
};

export default TestStatusBadge;

