 16→
 17→const { blue, gray } = palette;
 18→
 19→interface TableSearchPopoverProps {
 20→  "data-cy"?: string;
 21→  onConfirm: (search: string) => void;
 22→  placeholder?: string;
 23→  value: string;
 24→}
 25→
 26→const TableSearchPopover: React.FC<TableSearchPopoverProps> = ({
 27→  "data-cy": dataCy,
 28→  onConfirm,
 29→  placeholder,
 30→  value,
 31→}) => {
 32→  const [input, setInput] = useState(value);
 33→  const [active, setActive] = useState(false);
 34→  const iconColor = value === "" ? gray.dark2 : blue.base;
 35→
 36→  const [inputRef, setInputRef] = useState<HTMLInputElement | null>(null);
 37→  const buttonRef = useRef<HTMLButtonElement>(null);
 38→  const popoverRef = useRef<HTMLDivElement>(null);
 39→
 40→  // Handle onClickOutside
 41→  useOnClickOutside([buttonRef, popoverRef], () => setActive(false));
 42→
 43→  // If the value from the props has changed, update the input.
 44→  useEffect(() => {
 45→    setInput(value);
 46→  }, [value]);
 47→
 48→  const onEnter = () => {
 49→    onConfirm(input);
 50→    setActive(false);
 51→  };
 52→
 53→  useEffect(() => {
 54→    inputRef?.focus();
 55→    inputRef?.select();
 56→  }, [inputRef]);
 57→
 58→  return (
 59→    <FilterWrapper>
 60→      {/* eslint-disable-next-line @typescript-eslint/ban-ts-comment */}
 61→      {/* @ts-ignore: LeafyGreen component throws JSX errors */}
 62→      <IconButton
 63→        ref={buttonRef}
 64→        active={active}
 65→        aria-label="Table Search Popover Icon"
 66→        data-cy={dataCy}
 67→        onClick={() => setActive(!active)}
 68→      >
 69→        <Icon color={iconColor} glyph="MagnifyingGlass" />
 70→      </IconButton>
 71→      <Popover
 72→        active={active}
 73→        align={Align.Bottom}
