import { useRef, useState } from 'react';
import type { Meta, StoryObj } from '@storybook/react-vite';
import { expect } from 'storybook/test';
import { Button } from '@leafygreen-ui/button';
import Popconfirm from './index';

const meta = {
  component: Popconfirm,
  tags: ['ai-generated'],
} satisfies Meta<typeof Popconfirm>;

export default meta;
type Story = StoryObj<typeof meta>;

export const Default: Story = {
  render: () => {
    const [open, setOpen] = useState(false);
    const ref = useRef<HTMLButtonElement>(null);
    return (
      <div style={{ padding: '100px' }}>
        <Button ref={ref} onClick={() => setOpen(true)}>
          Delete Item
        </Button>
        <Popconfirm
          open={open}
          refEl={ref}
          setOpen={setOpen}
        >
          Are you sure you want to delete this item?
        </Popconfirm>
      </div>
    );
  },
  play: async ({ canvas, userEvent }) => {
    const trigger = canvas.getByRole('button', { name: /delete item/i });
    await expect(trigger).toBeVisible();
    await userEvent.click(trigger);
    await expect(canvas.getByText('Are you sure you want to delete this item?')).toBeVisible();
  },
};

export const WithCustomConfirmText: Story = {
  render: () => {
    const [open, setOpen] = useState(false);
    const ref = useRef<HTMLButtonElement>(null);
    return (
      <div style={{ padding: '100px' }}>
        <Button ref={ref} onClick={() => setOpen(true)}>
          Reset Settings
        </Button>
        <Popconfirm
          confirmText="Confirm Reset"
          open={open}
          refEl={ref}
          setOpen={setOpen}
        >
          This will reset all settings to their defaults.
        </Popconfirm>
      </div>
    );
  },
  play: async ({ canvas, userEvent }) => {
    const trigger = canvas.getByRole('button', { name: /reset settings/i });
    await userEvent.click(trigger);
    await expect(canvas.getByRole('button', { name: /confirm reset/i })).toBeVisible();
    await expect(canvas.getByRole('button', { name: /cancel/i })).toBeVisible();
  },
};

export const CancelAction: Story = {
  render: () => {
    const [open, setOpen] = useState(true);
    const ref = useRef<HTMLButtonElement>(null);
    return (
      <div style={{ padding: '100px' }}>
        <Button ref={ref} onClick={() => setOpen(true)}>
          Trigger
        </Button>
        <Popconfirm
          open={open}
          refEl={ref}
          setOpen={setOpen}
        >
          Do you want to proceed?
        </Popconfirm>
      </div>
    );
  },
  play: async ({ canvas, userEvent }) => {
    await expect(canvas.getByText('Do you want to proceed?')).toBeVisible();
    const cancelBtn = canvas.getByRole('button', { name: /cancel/i });
    await userEvent.click(cancelBtn);
  },
};

