  component: SomeComponent,
  tags: ['ai-generated'],
} satisfies Meta<typeof SomeComponent>;

export default meta;
type Story = StoryObj<typeof meta>;

export const Default: Story = {
  render: () => <SomeComponent variant="primary" disabled={false} />,
