  args: {
    variant: 'primary',
    disabled: true,
    children: 'Save',
  },
  play: async ({ canvas }) => {
    await expect(canvas.getByRole('button')).toBeDisabled();
  },
};
```

Use `render` when the story needs composition — wrapping the component in layout, combining multiple components, or passing children as JSX:

```tsx
