  1→import { useState, useEffect, useRef } from "react";
  2→import styled from "@emotion/styled";
  3→import { Icon } from "@leafygreen-ui/icon";
  4→import { IconButton } from "@leafygreen-ui/icon-button";
  5→import { palette } from "@leafygreen-ui/palette";
  6→import { Popover, Align, Justify } from "@leafygreen-ui/popover";
  7→import {
  8→  SearchInput,
  9→  Size as SearchInputSize,
 10→} from "@leafygreen-ui/search-input";
 11→import { Description } from "@leafygreen-ui/typography";
 12→import { size } from "../../../../constants/tokens";
 13→import { useOnClickOutside } from "../../../../hooks";
 14→import { PopoverContainer } from "../../../styles/Popover";
 15→import { DEFAULT_SPACING, FilterWrapper } from "../constants";
 16→
 17→const { blue, gray } = palette;
 18→
 19→interface TableSearchPopoverProps {
 20→  "data-cy"?: string;
 21→  onConfirm: (search: string) => void;
 22→  placeholder?: string;
 23→  value: string;
 24→}
 25→
 26→const TableSearchPopover: React.FC<TableSearchPopoverProps> = ({
 27→  "data-cy": dataCy,
 28→  onConfirm,
 29→  placeholder,
 30→  value,
 31→}) => {
 32→  const [input, setInput] = useState(value);
 33→  const [active, setActive] = useState(false);
 34→  const iconColor = value === "" ? gray.dark2 : blue.base;
 35→
 36→  const [inputRef, setInputRef] = useState<HTMLInputElement | null>(null);
 37→  const buttonRef = useRef<HTMLButtonElement>(null);
 38→  const popoverRef = useRef<HTMLDivElement>(null);
 39→
 40→  // Handle onClickOutside
 41→  useOnClickOutside([buttonRef, popoverRef], () => setActive(false));
 42→
 43→  // If the value from the props has changed, update the input.
 44→  useEffect(() => {
 45→    setInput(value);
 46→  }, [value]);
 47→
 48→  const onEnter = () => {
 49→    onConfirm(input);
 50→    setActive(false);
 51→  };
 52→
 53→  useEffect(() => {
 54→    inputRef?.focus();
 55→    inputRef?.select();
 56→  }, [inputRef]);
 57→
 58→  return (
 59→    <FilterWrapper>
 60→      {/* eslint-disable-next-line @typescript-eslint/ban-ts-comment */}
 61→      {/* @ts-ignore: LeafyGreen component throws JSX errors */}
 62→      <IconButton
 63→        ref={buttonRef}
 64→        active={active}
 65→        aria-label="Table Search Popover Icon"
 66→        data-cy={dataCy}
 67→        onClick={() => setActive(!active)}
 68→      >
 69→        <Icon color={iconColor} glyph="MagnifyingGlass" />
 70→      </IconButton>
 71→      <Popover
 72→        active={active}
 73→        align={Align.Bottom}
 74→        justify={Justify.Middle}
 75→        refEl={buttonRef}
 76→        spacing={DEFAULT_SPACING}
 77→      >
 78→        <PopoverContainer ref={popoverRef} data-cy={`${dataCy}-wrapper`}>
 79→          <InputContainer>
 80→            <Description>Press enter to filter.</Description>
 81→            <SearchInput
 82→              ref={(el) => setInputRef(el)}
 83→              aria-label="Search table"
 84→              data-cy={`${dataCy}-input-filter`}
 85→              onChange={(e) => setInput(e.target.value)}
 86→              onKeyDown={(e) => e.key === "Enter" && onEnter()}
 87→              placeholder={placeholder}
 88→              size={SearchInputSize.Small}
 89→              value={input}
 90→            />
 91→          </InputContainer>
 92→        </PopoverContainer>
 93→      </Popover>
 94→    </FilterWrapper>
 95→  );
 96→};
 97→
 98→export default TableSearchPopover;
