 5→interface ProtectedRouteProps {
 6→  children: React.ReactElement;
 7→  loginPageRoute: string;
 8→}
 9→
10→const ProtectedRoute: React.FC<ProtectedRouteProps> = ({
11→  children,
12→  loginPageRoute,
13→}) => {
14→  const { hasCheckedAuth, isAuthenticated } = useAuthProviderContext();
15→  const location = useLocation();
16→
17→  if (!isAuthenticated && hasCheckedAuth) {
18→    // Redirect to login and preserve the location state to come back after logging in.
